+func TestFeaturesValidatorReportsEachSourceLocation(t *testing.T) {
+	validator, err := NewFeaturesValidator()
+	require.NoError(t, err)
+
+	result, err := validator.Validate("features.yaml", []byte(invalidFeatures))
+	require.ErrorIs(t, err, ErrValidationFailed)
+	require.Len(t, result.Errors, 5)
+
+	want := map[string]struct {
+		line, column int
+		message      string
+	}{
+		"flags.0.ey":                              {4, 3, "field not allowed"},
+		"flags.0.nabled":                          {7, 3, "field not allowed"},
+		"flags.0.variants.0.escription":           {11, 5, "field not allowed"},
+		"flags.0.rules.0.distributions.0.rollout": {17, 16, "out of bound <=100"},
